import{_ as o,C as r,c as s,o as i,a3 as t,G as a}from"./chunks/framework.Dokpd4od.js";const k=JSON.parse('{"title":"Bank accounts","description":"","frontmatter":{},"headers":[],"relativePath":"master/finance/payments/bank-accounts.md","filePath":"master/finance/payments/bank-accounts.md","lastUpdated":1792041590000}'),c={name:"master/finance/payments/bank-accounts.md"};function l(u,e,d,h,g,m){const n=r("ImagePopup");return i(),s("div",null,[e[0]||(e[0]=t('<h1 id="bank-accounts" tabindex="-1">Bank accounts <a class="header-anchor" href="#bank-accounts" aria-label="Permalink to &quot;Bank accounts&quot;">​</a></h1><p>A bank account record stores the account number of a partner and the bank it belongs to. You use it when you pay a vendor, so the payment carries the right recipient details. You can keep these records for customers too.</p><blockquote><p><strong>In simple words:</strong> Bank accounts are the address book of money. Save them once and pick them when you pay.</p></blockquote><h2 id="where-to-find-bank-accounts" tabindex="-1">Where to find bank accounts <a class="header-anchor" href="#where-to-find-bank-accounts" aria-label="Permalink to &quot;Where to find bank accounts&quot;">​</a></h2><ul><li>Invoices app: <code>Invoices → Configurations → Bank Accounts</code>.</li><li>On a customer or vendor: open the contact and use its bank accounts section. See <a href="./../../getting-started/contacts/contacts.html">Contacts</a> and <a href="./../../getting-started/contacts/contacts.html">Vendors</a>.</li></ul><p>The menu item <strong>Bank Accounts</strong> is in the Invoices app. The Accounting app does not list it in its menu. The records are shared, so a bank account saved in one place shows up everywhere.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The list has the tabs <strong>All</strong> and <strong>Archived</strong>.</p>',8)),a(n,{src:"/images1/finance/bank_accounts_list.png",alt:"Bank Accounts list at Invoices → Configurations → Bank Accounts with columns Account Number, Bank, Account Holder"}),e[1]||(e[1]=t('<h3 id="columns" tabindex="-1">Columns <a class="header-anchor" href="#columns" aria-label="Permalink to &quot;Columns&quot;">​</a></h3><ul><li><strong><em>Account Number:</em></strong> The account number.</li><li><strong><em>Bank:</em></strong> The name of the bank, for example <strong>Bank of California</strong>.</li><li><strong><em>Account Holder:</em></strong> The partner who owns the account.</li><li><strong><em>Can Send Money:</em></strong> Hidden by default. Turn it on from the column toggle.</li><li><strong><em>Created At</em></strong>, <strong><em>Updated At</em></strong> and <strong><em>Deleted At</em>:</strong> Hidden by default.</li></ul><h3 id="group-and-filter" tabindex="-1">Group and filter <a class="header-anchor" href="#group-and-filter" aria-label="Permalink to &quot;Group and filter&quot;">​</a></h3><ul><li>Click <strong>Group by</strong> to group by <strong>Bank</strong>, <strong>Can Send Money</strong> or <strong>Created At</strong>.</li><li>Click the filter button to filter by <strong>Bank</strong>, <strong>Account Holder</strong>, <strong>Creator</strong> or <strong>Can Send Money</strong>.</li></ul><h2 id="create-a-bank-account" tabindex="-1">Create a bank account <a class="header-anchor" href="#create-a-bank-account" aria-label="Permalink to &quot;Create a bank account&quot;">​</a></h2><ol><li>Open <code>Invoices → Configurations → Bank Accounts</code>.</li><li>Click <strong>New Bank Account</strong>.</li><li>Fill in the form.</li><li>Click <strong>Create</strong>.</li></ol>',6)),a(n,{src:"/images1/finance/bank_account_form.png",alt:"The bank account form with Account Number 2986603721706, Bank Bank of China, Account Holder Ben Foster"}),e[2]||(e[2]=t('<h3 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to &quot;Fields&quot;">​</a></h3><ul><li><strong><em>Account Number:</em></strong> Required. It must be unique. Type the number as the bank gives it.</li><li><strong><em>Can Send Money:</em></strong> A switch. Turn it on when you have checked that this account is safe to pay.</li><li><strong><em>Bank:</em></strong> Required. Pick the bank. Deleted banks cannot be picked.</li><li><strong><em>Account Holder:</em></strong> Required. The customer or vendor who owns the account. When you open the form from a contact, this field is already filled.</li></ul><h2 id="how-bank-accounts-are-used" tabindex="-1">How bank accounts are used <a class="header-anchor" href="#how-bank-accounts-are-used" aria-label="Permalink to &quot;How bank accounts are used&quot;">​</a></h2><ul><li>On a vendor bill, the <strong>Recipient Bank</strong> field in <strong>Other Information</strong> offers the vendor accounts.</li><li>In the <strong>Pay</strong> window of a bill, the <strong>Recipient Bank Account</strong> field lists the same accounts. See <a href="./register-payment.html">Register a payment</a>.</li><li>On a manual payment, <strong>Vendor Bank Account</strong> or <strong>Customer Bank Account</strong> offers the accounts of the chosen partner. See <a href="./manage-payments.html">Manage payments</a>.</li><li>Aureus shows the bank account field only for the method <strong>Manual Payment</strong> on a bank journal. It does not show on a cash journal.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>An account with <strong>Can Send Money</strong> turned on is listed first when you pick a recipient bank.</p></div><h2 id="edit-delete-and-archive" tabindex="-1">Edit, delete and archive <a class="header-anchor" href="#edit-delete-and-archive" aria-label="Permalink to &quot;Edit, delete and archive&quot;">​</a></h2><ul><li>Click <strong>Edit</strong> on a row to change a record.</li><li>Click <strong>Delete</strong> to archive it. An archived account moves to the <strong>Archived</strong> tab and shows &quot;(Deleted)&quot; in lists. You cannot pick it again.</li></ul><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>You pay vendor FreshFoods Wholesale for bill BILL/2026/4. First you add their account: <strong>Account Number</strong> <code>1234567890</code>, <strong>Bank</strong> <strong>First National Bank</strong>, <strong>Account Holder</strong> FreshFoods Wholesale. Then you open the bill, click <strong>Pay</strong>, and pick that account as the <strong>Recipient Bank Account</strong>.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./register-payment.html">Register a payment</a></li><li><a href="./manage-payments.html">Manage payments</a></li><li><a href="./../../getting-started/contacts/contacts.html">Vendors</a></li></ul>',11))])}const b=o(c,[["render",l]]);export{k as __pageData,b as default};
